import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

export interface AuthResult {
  ok: boolean;
  response?: {
    body: Record<string, unknown>;
    status: number;
  };
}

export interface Proposal {
  id?: string;
  timestamp?: string | number;
  action: string;
  data?: Record<string, unknown>;
  details?: Record<string, unknown>;
  status?: string;
}

class ProposalsManager {
  private proposalsDir: string;

  constructor() {
    this.proposalsDir = path.join(process.cwd(), ".qmoi_proposals");
    this.ensureDir();
  }

  private ensureDir() {
    if (!fs.existsSync(this.proposalsDir)) {
      fs.mkdirSync(this.proposalsDir, { recursive: true });
    }
  }

  /**
   * Validates API key from request headers
   * Checks for MASTER_TOKEN or API_KEY in Authorization header
   */
  requireApiKey(headers: Headers): AuthResult {
    try {
      const authHeader = headers.get("authorization");
      const apiKeyHeader = headers.get("x-api-key");
      const masterToken = process.env.MASTER_TOKEN;

      // Allow requests in development
      if (process.env.NODE_ENV === "development") {
        return { ok: true };
      }

      // Check for valid API key
      if (authHeader) {
        const token = authHeader.replace("Bearer ", "");
        if (token === masterToken || token === process.env.API_KEY) {
          return { ok: true };
        }
      }

      if (
        apiKeyHeader === masterToken ||
        apiKeyHeader === process.env.API_KEY
      ) {
        return { ok: true };
      }

      return {
        ok: false,
        response: {
          body: { error: "Unauthorized - Invalid API key" },
          status: 401,
        },
      };
    } catch (error) {
      return {
        ok: false,
        response: {
          body: { error: "Authentication error" },
          status: 500,
        },
      };
    }
  }

  /**
   * Writes a proposal to disk for audit/tracking
   */
  async writeProposal(proposal: any): Promise<any> {
    try {
      this.ensureDir();
      const id =
        proposal.id ||
        `proposal_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      const filePath = path.join(this.proposalsDir, `${id}.json`);

      const proposalData = {
        ...proposal,
        id,
        timestamp: proposal.timestamp || Date.now(),
        status: proposal.status || "pending",
      };

      fs.writeFileSync(filePath, JSON.stringify(proposalData, null, 2));
      return proposalData;
    } catch (error) {
      console.error("Error writing proposal:", error);
      // Don't throw - allow operation to continue even if proposal logging fails
    }
  }

  /**
   * Reads a proposal from disk
   */
  async readProposal(id: string): Promise<Proposal | null> {
    try {
      const filePath = path.join(this.proposalsDir, `${id}.json`);
      if (!fs.existsSync(filePath)) {
        return null;
      }
      const data = fs.readFileSync(filePath, "utf-8");
      return JSON.parse(data);
    } catch (error) {
      console.error("Error reading proposal:", error);
      return null;
    }
  }

  /**
   * Lists all proposals
   */
  async listProposals(): Promise<Proposal[]> {
    try {
      this.ensureDir();
      const files = fs.readdirSync(this.proposalsDir);
      const proposals: Proposal[] = [];

      for (const file of files) {
        if (file.endsWith(".json")) {
          const data = fs.readFileSync(
            path.join(this.proposalsDir, file),
            "utf-8"
          );
          proposals.push(JSON.parse(data));
        }
      }

      return proposals;
    } catch (error) {
      console.error("Error listing proposals:", error);
      return [];
    }
  }

  /**
   * Updates proposal status
   */
  async updateProposalStatus(id: string, status: string): Promise<void> {
    try {
      const proposal = await this.readProposal(id);
      if (proposal) {
        proposal.status = status;
        await this.writeProposal(proposal);
      }
    } catch (error) {
      console.error("Error updating proposal:", error);
    }
  }
}

// Export singleton instance
const libProposals = new ProposalsManager();
export default libProposals;

// Export individual methods for named imports
export const requireApiKey = libProposals.requireApiKey.bind(libProposals);
export const writeProposal = libProposals.writeProposal.bind(libProposals);
export const readProposal = libProposals.readProposal.bind(libProposals);
export const listProposals = libProposals.listProposals.bind(libProposals);
export const updateProposalStatus =
  libProposals.updateProposalStatus.bind(libProposals);
